const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function databaseShopId(name){try{return JSON.parse(localStorage.getItem('zwconnect-shop-database-ids')||'{}')[name]||null}catch{return null}}
function tradeModeLabel(mode){return mode==='wholesale'?'Wholesale':mode==='hybrid'?'Wholesale & retail':'Retail'}
async function queueAdminAction(type,payload,message){await window.ZWOffline.enqueue(type,payload,{role:'site_admin'});toast(navigator.onLine?`${message} — awaiting Supabase confirmation`:`${message} — saved offline`,'cloud-upload')}
async function restoreQueuedAdminActions(){for(const action of await window.ZWOffline.list()){if(action.role!=='site_admin')continue;const p=action.payload;if(action.type==='application.review'){const application=applications.find(a=>String(a.id)===String(p.applicationId));if(application)application.status=p.decision}if(action.type==='shop.update'){const shop=businesses.find(b=>b[0]===p.shopName);if(shop){shop[0]=p.changes.name||shop[0];shop[3]=p.changes.city||shop[3];shop[5]=p.changes.sales_mode||shop[5]}}if(action.type==='shop.delete'){const index=businesses.findIndex(b=>b[0]===p.shopName);if(index>=0)businesses.splice(index,1);subscriptions=subscriptions.filter(s=>s.shop!==p.shopName)}if(action.type==='subscription.update'){const subscription=subscriptions.find(s=>s.shop===p.shopName);if(subscription)Object.assign(subscription,{amount:p.amount,duration:p.duration,trial:p.trial,status:p.status})}}if(document.body.classList.contains('admin-ready'))render()}
function updateAdminSync(status){const button=$('#adminSyncStatus');if(!button)return;button.className=`admin-sync-status ${!status.online?'offline':status.syncing?'syncing':status.failed?'failed':'online'}`;button.querySelector('span').title=status.online?'Online':'Offline';button.querySelector('[data-lucide]')?.setAttribute('data-lucide',!status.online?'cloud-off':status.syncing?'refresh-cw':status.failed?'cloud-alert':'cloud-check');button.querySelector('b').textContent=!status.online?'Offline':status.syncing?'Syncing':status.pending&&!window.zwconnectSupabase?'Cloud setup needed':status.failed?'Needs attention':'Synced';button.querySelector('small').textContent=`${status.pending} pending`;icons()}
function openApplicationDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open('zwconnect-applications',1);request.onupgradeneeded=()=>request.result.createObjectStore('applications',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function loadSubmittedApplications(){try{const db=await openApplicationDb(),records=await new Promise((resolve,reject)=>{const request=db.transaction('applications').objectStore('applications').getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});db.close();records.forEach(record=>{if(!applications.some(a=>a.id===record.id))applications.unshift({...record,proof:{...record.proof,url:URL.createObjectURL(record.proofFile)}})})}catch{}}
function icons(){if(window.lucide)lucide.createIcons()}
function metric(icon,label,value){return `<article class="metric"><span><i data-lucide="${icon}"></i></span><div><small>${label}</small><strong>${value}</strong></div></article>`}
function table(headers,rows){return `<div class="table-wrap"><table class="admin-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function pending(){return applications.filter(a=>a.status==='pending')}
function updateBadges(){$('#pendingBadge').textContent=pending().length;$('#pendingBadge').style.display=pending().length?'inline-block':'none';const cb=$('#courierBadge'),count=courierApplications.filter(c=>c.status==='pending').length;if(cb){cb.textContent=count;cb.style.display=count?'inline-block':'none'}}
function toast(text,icon='circle-check'){const t=$('#adminToast');t.innerHTML=`<i data-lucide="${icon}"></i><span>${text}</span>`;icons();t.classList.add('show');clearTimeout(window.adminToastTimer);window.adminToastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function renderOverview(){const p=pending();$('#adminContent').innerHTML=`<div class="metric-grid">${metric('store','Approved businesses',18)}${metric('clipboard-clock','Pending owners',p.length)}${metric('users','Platform accounts',47)}${metric('map-pinned','Cities covered',6)}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>New businesses</h2><p>Approved shops joining the network</p></div><button data-view-link="businesses">View all</button></div><div class="chart">${[42,64,51,78,68,93,82].map((h,i)=>`<div class="bar" style="height:${h}%"><span>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest platform events</p></div></div><div class="activity-list">${audit.slice(0,4).map((a,i)=>`<div class="activity"><span><i data-lucide="${['badge-check','shield-alert','user-plus','layout-grid'][i]}"></i></span><div><strong>${a[0]}</strong><small>${a[1]} • ${a[2]}</small></div><time>${a[3].split(',')[1]}</time></div>`).join('')}</div></section></div><section class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Owner approvals requiring attention</h2><p>Review identity and business details before granting owner access</p></div><span class="status">${p.length} pending</span></div>${approvalTable(p.slice(0,3))}</section>`}
function approvalTable(list){return table(['Owner','Business','Profile','Trading model','City','Proof','Applied','Decision'],list.length?list.map(a=>`<tr><td><strong>${a.owner}</strong></td><td>${a.business}</td><td>${a.profile}</td><td><span class="status active">${tradeModeLabel(a.salesMode)}</span></td><td>${a.city}</td><td><a class="proof-link" href="${a.proof.url}" target="_blank" rel="noopener" title="${a.proof.name}">View proof</a></td><td>${a.date}</td><td><button data-approve="${a.id}">Approve</button><button class="danger" data-reject="${a.id}">Reject</button></td></tr>`):['<tr><td colspan="8">No applications are waiting for review.</td></tr>'])}
function renderApprovals(){$('#adminContent').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Owner registration approvals</h2><p>Only approved owners can create shops or worker accounts</p></div><span class="status">${pending().length} pending</span></div>${approvalTable(pending())}</section>`}
function renderBusinesses(){$('#adminContent').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Business directory</h2><p>Retail, wholesale and hybrid shops with separate pricing rules.</p></div><button>Export list</button></div>${table(['Business','Profile','Trading model','Owner','City','Status','Actions'],businesses.map((b,i)=>`<tr><td><strong>${b[0]}</strong></td><td>${b[1]}</td><td><span class="status active">${tradeModeLabel(b[5])}</span></td><td>${b[2]}</td><td>${b[3]}</td><td><span class="status ${b[4]}">${b[4]}</span></td><td><span class="shop-actions"><button data-business="${i}">Review</button><button class="edit" data-edit-shop="${i}">Edit</button><button class="danger" data-delete-shop="${i}">Delete</button></span></td></tr>`))}</section>`}
function renderCouriers(){const pendingCouriers=courierApplications.filter(c=>c.status==='pending');$('#adminContent').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Courier approvals</h2><p>Verify identity, bicycle details and operating city before listing a courier.</p></div><span class="status">${pendingCouriers.length} pending</span></div>${table(['Applicant','Courier','City','Identity & bicycle','Decision'],pendingCouriers.length?pendingCouriers.map(c=>`<tr><td><strong>${c.name}</strong><small>${c.email} • ${c.phone}</small></td><td>${c.business}</td><td>${c.city}</td><td><strong>${c.nationalId}</strong><small>${c.bike}</small></td><td><button data-approve-courier="${c.id}">Approve</button><button class="danger" data-reject-courier="${c.id}">Reject</button></td></tr>`):['<tr><td colspan="5">No courier applications are waiting.</td></tr>'])}</section><section class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Approved courier network</h2><p>Rates are courier-managed; subscriptions and access are admin-managed.</p></div><a href="../courier/?demo=1" target="_blank">Open courier portal</a></div>${table(['Courier','Rider','City','Public rate','Subscription','Actions'],couriers.map(c=>`<tr><td><strong>${c.name}</strong></td><td>${c.rider}</td><td>${c.city}</td><td>${c.rate}</td><td><span class="status ${c.subscription==='active'?'active':'approved'}">${c.subscription}</span><small>US$ ${c.amount} / ${c.duration} days</small></td><td><button data-courier-subscription="${c.id}">Edit plan</button><button class="danger" data-suspend-courier="${c.id}">${c.status==='active'?'Suspend':'Activate'}</button></td></tr>`))}</section>`}
function renderSubscriptions(){$('#adminContent').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Shop subscriptions</h2><p>Set platform access amount, duration, trial period and status.</p></div><span class="status">Admin only</span></div><form class="subscription-form" id="subscriptionForm"><select name="shop" aria-label="Shop">${businesses.map(b=>`<option>${b[0]}</option>`).join('')}</select><input name="amount" type="number" min="0" step="0.01" value="25" aria-label="Amount in USD" placeholder="Amount USD" required><input name="duration" type="number" min="1" value="30" aria-label="Duration in days" placeholder="Duration days" required><input name="trial" type="number" min="0" value="0" aria-label="Trial days" placeholder="Trial days"><select name="status" aria-label="Status"><option value="active">Active</option><option value="trial">Trial</option><option value="past_due">Past due</option><option value="suspended">Suspended</option><option value="cancelled">Cancelled</option></select><button class="primary" type="submit">Save subscription</button></form><div class="subscription-note">Shop owners can view only their own subscription. Workers and public visitors cannot access subscription data.</div>${table(['Shop','Amount','Duration','Trial','Status','Access until','Action'],subscriptions.map((s,i)=>`<tr><td><strong>${s.shop}</strong></td><td>US$ ${Number(s.amount).toFixed(2)}</td><td>${s.duration} days</td><td>${s.trial?s.trial+' days':'—'}</td><td><span class="status ${s.status==='active'?'active':s.status==='trial'?'approved':'suspended'}">${s.status.replace('_',' ')}</span></td><td>${s.ends}</td><td><button class="edit" data-edit-subscription="${i}">Edit</button></td></tr>`))}</section>`}
function renderAccounts(){$('#adminContent').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Platform accounts</h2><p>One non-overlapping platform role per authenticated user</p></div></div>${table(['Name','Email','Role','Scope','Status'],accounts.map(a=>`<tr><td><strong>${a[0]}</strong></td><td>${a[1]}</td><td>${a[2]}</td><td>${a[3]}</td><td><span class="status ${a[4]}">${a[4]}</span></td></tr>`))}</section>`}
function renderProfiles(){$('#adminContent').innerHTML=`<div class="module-grid">${profiles.map((p,i)=>`<article class="module-card"><span><i data-lucide="layout-grid"></i></span><h3>${p}</h3><p>${i<2?'Multiple approved shops':'Profile enabled'} • Public discovery active</p></article>`).join('')}</div>`}
function renderAudit(){$('#adminContent').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Immutable audit trail</h2><p>Administrative, owner and worker security events</p></div><button>Export CSV</button></div>${table(['Event','Actor','Entity','Timestamp'],audit.map(a=>`<tr><td><strong>${a[0]}</strong></td><td>${a[1]}</td><td><code>${a[2]}</code></td><td>${a[3]}</td></tr>`))}</section>`}
function renderGeneric(view){const data={moderation:['shield-alert','Moderation centre','Review reports, suspended listings and catalogue policy issues.'],settings:['settings-2','Platform settings','Configure marketplace policies, notifications and system defaults.']}[view];$('#adminContent').innerHTML=`<section class="panel"><div class="empty-module"><span><i data-lucide="${data[0]}"></i></span><h2>${data[1]}</h2><p>${data[2]} This area is restricted to the site_admin platform role.</p></div></section>`}
function render(){const titles={overview:'Network overview',approvals:'Owner approvals',businesses:'Business directory',couriers:'Courier network',subscriptions:'Shop subscriptions',accounts:'Platform accounts',profiles:'Business profiles',moderation:'Moderation centre',audit:'Audit log',settings:'Platform settings'};$('#viewTitle').textContent=titles[currentView];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));if(currentView==='overview')renderOverview();else if(currentView==='approvals')renderApprovals();else if(currentView==='businesses')renderBusinesses();else if(currentView==='couriers')renderCouriers();else if(currentView==='subscriptions')renderSubscriptions();else if(currentView==='accounts')renderAccounts();else if(currentView==='profiles')renderProfiles();else if(currentView==='audit')renderAudit();else renderGeneric(currentView);updateBadges();icons()}
function unlock(){$('body').className='admin-ready';$('#adminShell').setAttribute('aria-hidden','false');render();icons()}
function lock(){$('body').className='admin-locked';$('#adminShell').setAttribute('aria-hidden','true');$('#adminSidebar').classList.remove('open');icons()}
document.addEventListener('click',async event=>{if(!event.target.closest('#adminSignOut'))return;try{await window.zwconnectSupabase?.auth.signOut({scope:'local'})}catch{}await window.ZWOffline?.setContext('public',{userId:null,email:null,shopId:null,force:true})},{capture:true});
document.addEventListener('DOMContentLoaded',()=>{icons();window.ZWOffline?.setContext('site_admin');restoreQueuedAdminActions();window.ZWOffline?.subscribe(updateAdminSync);if(navigator.onLine)window.ZWOffline?.flush();loadSubmittedApplications().then(()=>{if(document.body.classList.contains('admin-ready'))render()});let reservedLogin=false;try{reservedLogin=sessionStorage.getItem('zwconnect_admin_email')==='dylankoshita96@gmail.com';sessionStorage.removeItem('zwconnect_admin_email')}catch{}if(new URLSearchParams(location.search).get('demo')==='1'||reservedLogin)unlock();$('#adminLogin').addEventListener('submit',e=>{e.preventDefault();const email=new FormData(e.currentTarget).get('email')?.trim().toLowerCase();if(email!=='dylankoshita96@gmail.com'){toast('This account is not authorised for site administration','shield-x');return}unlock();toast('Signed in to the dedicated admin portal')});$('#adminMenu').addEventListener('click',()=>$('#adminSidebar').classList.toggle('open'));$('#adminSignOut').addEventListener('click',lock);$('#adminSyncStatus').addEventListener('click',()=>window.ZWOffline?.flush());$('#adminSearch').addEventListener('keydown',e=>{if(e.key==='Enter')toast(`Searching for “${e.target.value}”`,'search')});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#adminSearch').focus()}if(e.key==='Escape')$('#adminSidebar').classList.remove('open')});document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){currentView=nav.dataset.view;render();$('#adminSidebar').classList.remove('open')}const link=e.target.closest('[data-view-link]');if(link){currentView=link.dataset.viewLink;render()}const approve=e.target.closest('[data-approve]');if(approve){const a=applications.find(x=>String(x.id)===approve.dataset.approve);a.status='approved';queueAdminAction('application.review',{applicationId:a.id,decision:'approved',slug:a.business.toLowerCase().replace(/[^a-z0-9]+/g,'-')},`${a.business} approval saved`);render()}const reject=e.target.closest('[data-reject]');if(reject){const a=applications.find(x=>String(x.id)===reject.dataset.reject);a.status='rejected';queueAdminAction('application.review',{applicationId:a.id,decision:'rejected',reason:'Rejected by site administrator'},`${a.business} rejection saved`);render()}const review=e.target.closest('[data-business]');if(review)toast(`Reviewing ${businesses[Number(review.dataset.business)][0]}`,'store')});});
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-shop]');if(edit){const i=Number(edit.dataset.editShop),shop=businesses[i],name=prompt('Shop name',shop[0]),city=name&&prompt('Shop city',shop[3]),mode=city&&prompt('Trading model: retail, wholesale or hybrid',shop[5]);if(name&&city&&mode){const cleanMode=mode.trim().toLowerCase();if(!['retail','wholesale','hybrid'].includes(cleanMode)){toast('Trading model must be retail, wholesale or hybrid','shield-alert');return}const old=shop[0],shopId=databaseShopId(old);shop[0]=name.trim();shop[3]=city.trim();shop[5]=cleanMode;const sub=subscriptions.find(s=>s.shop===old);if(sub)sub.shop=shop[0];queueAdminAction('shop.update',{shopId,shopName:old,changes:{name:shop[0],city:shop[3],sales_mode:shop[5]}},`${shop[0]} update saved`);renderBusinesses()}}const remove=e.target.closest('[data-delete-shop]');if(remove){const i=Number(remove.dataset.deleteShop),name=businesses[i][0],shopId=databaseShopId(name);if(confirm(`Delete ${name}? Products, workers and subscription access will be removed.`)){businesses.splice(i,1);subscriptions=subscriptions.filter(s=>s.shop!==name);queueAdminAction('shop.delete',{shopId,shopName:name},`${name} deletion saved`);renderBusinesses()}}const editSub=e.target.closest('[data-edit-subscription]');if(editSub){const s=subscriptions[Number(editSub.dataset.editSubscription)],form=$('#subscriptionForm');form.shop.value=s.shop;form.amount.value=s.amount;form.duration.value=s.duration;form.trial.value=s.trial;form.status.value=s.status;form.scrollIntoView({behavior:'smooth',block:'center'})}});
document.addEventListener('submit',e=>{if(e.target.id!=='subscriptionForm')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),existing=subscriptions.find(s=>s.shop===data.shop),record={shop:data.shop,amount:Number(data.amount),duration:Number(data.duration),trial:Number(data.trial||0),status:data.status,ends:data.status==='trial'?`${data.trial||0} trial days`:data.status==='cancelled'?'—':`${data.duration} days from activation`};if(existing)Object.assign(existing,record);else subscriptions.push(record);queueAdminAction('subscription.update',{shopId:databaseShopId(data.shop),shopName:data.shop,amount:record.amount,duration:record.duration,trial:record.trial,status:record.status},`${data.shop} subscription saved`);renderSubscriptions()});
document.addEventListener('click',e=>{const approve=e.target.closest('[data-approve-courier]');if(approve){const c=courierApplications.find(x=>x.id===approve.dataset.approveCourier);c.status='approved';couriers.push({id:crypto.randomUUID(),name:c.business,rider:c.name,city:c.city,rate:'US$ 2 + distance',subscription:'trial',amount:0,duration:14,status:'active'});queueAdminAction('courier_application.review',{applicationId:c.id,approve:true},`${c.business} courier approval saved`);renderCouriers()}const reject=e.target.closest('[data-reject-courier]');if(reject){const c=courierApplications.find(x=>x.id===reject.dataset.rejectCourier);c.status='rejected';queueAdminAction('courier_application.review',{applicationId:c.id,approve:false,reason:'Courier verification was not completed'},`${c.business} courier rejection saved`);renderCouriers()}const suspend=e.target.closest('[data-suspend-courier]');if(suspend){const c=couriers.find(x=>x.id===suspend.dataset.suspendCourier);c.status=c.status==='active'?'suspended':'active';toast(`${c.name} is now ${c.status}`,'bike');renderCouriers()}const edit=e.target.closest('[data-courier-subscription]');if(edit){const c=couriers.find(x=>x.id===edit.dataset.courierSubscription),amount=prompt('Courier subscription amount (USD)',c.amount),duration=amount&&prompt('Duration in days',c.duration),trial=duration&&prompt('Trial days',0),status=trial!==null&&prompt('Status: trial, active, past_due, suspended or cancelled',c.subscription);if(amount&&duration&&trial!==null&&status){c.amount=Number(amount);c.duration=Number(duration);c.subscription=status;queueAdminAction('courier_subscription.update',{courierId:c.id,amount:c.amount,duration:c.duration,trial:Number(trial),status},`${c.name} subscription saved`);renderCouriers()}}});
